def find_min_k():
    min_val = float('inf')
    for d in range(1, 1000):
        for c in range(1, 1000):
            y2 = c*c - 6*c*d + d*d
            if y2 >= 0:
                y = int(y2**0.5)
                if y*y == y2:
                    # Also need to check if a and b are integers.
                    # a+b = c+d, ab = 2cd
                    # a, b = ((c+d) +/- y) / 2
                    # They are integers if (c+d+y) is even and (c+d-y) is even.
                    # This is equivalent to (c+d) and y having the same parity.
                    if (c + d + y) % 2 == 0:
                        val = (c*c + d*d) / (c*d)
                        if val < min_val:
                            min_val = val
                            print(f"c={c}, d={d}, val={min_val}, y={y}")
    return min_val

